+
+    private SystemDataStreamMigrationInfo(
+        DataStream dataStream,
+        String dataStreamName,
+        String featureName,
+        String origin,
+        SystemIndices.Feature owningFeature
+    ) {
+        super(featureName, origin, owningFeature);
+        this.dataStreamName = dataStreamName;
