+    }
+
+    public static SystemDataStreamMigrationInfo build(
+        DataStream dataStream,
+        SystemDataStreamDescriptor dataStreamDescriptor,
+        SystemIndices.Feature feature
+    ) {
+        return new SystemDataStreamMigrationInfo(
+            dataStream,
